# 让进程优雅处理退出信号(C 语言)
// graceful.c
#include <signal.h>
#include <stdio.h>
#include <unistd.h>

volatile int running = 1;
void on_term(int sig) { running = 0; }

int main() {
  signal(SIGTERM, on_term);
  signal(SIGINT, on_term);
  while (running) {
    printf("working...\n");
    sleep(1);
  }
  printf("exited cleanly\n");
  return 0;
}
# 编译: gcc -g graceful.c -o graceful
# ./graceful & kill PID -> 会走到 cleanly 而非被强杀

