// 多线程累加(不安全版, 会随机出错)
#include <pthread.h>
#include <stdio.h>

long counter = 0;

void *worker(void *arg) {
  for (int i = 0; i < 100000; i++) counter++;
  return 0;
}

int main() {
  pthread_t t[4];
  for (int i = 0; i < 4; i++)
    pthread_create(&t[i], 0, worker, 0);
  for (int i = 0; i < 4; i++)
    pthread_join(t[i], 0);
  printf("counter = %ld\n", counter);   // 应 400000 但常更小
  return 0;
}
// gcc -pthread t.c -o t && ./t

