# fork + exec + wait 经典组合(C)
#include <unistd.h>
#include <sys/wait.h>
#include <stdio.h>

int main() {
  pid_t pid = fork();
  if (pid == 0) {
    // 子进程: 执行 ls
    execlp("ls", "ls", "-l", (char*)0);
    perror("exec"); return 1;
  }
  // 父进程: 等子进程结束并回收
  int status;
  waitpid(pid, &status, 0);
  printf("child exit status: %d\n",
         WEXITSTATUS(status));
  return 0;
}
// 编译: gcc fork.c -o fork && ./fork

