// pipe 父子通信: 子写 父读
#include <unistd.h>
#include <stdio.h>

int main() {
  int fd[2];
  pipe(fd);
  pid_t pid = fork();

  if (pid == 0) {
    close(fd[0]);
    write(fd[1], "hello from child", 17);
    close(fd[1]);
    return 0;
  }
  close(fd[1]);
  char buf[64];
  int n = read(fd[0], buf, sizeof buf - 1);
  buf[n] = 0;
  printf("parent got: %s\n", buf);
  return 0;
}
